function aplicarTemaGuardado(){"oscuro"===localStorage.getItem(CLAVE)?raiz.setAttribute("data-theme","oscuro"):raiz.removeAttribute("data-theme")}function sincronizarBoton(t){const e="oscuro"===raiz.getAttribute("data-theme");t.textContent=e?"Modo Claro":"Modo Dark",t.setAttribute("aria-label",e?"Activar modo claro":"Activar modo oscuro"),t.setAttribute("aria-pressed",String(e))}function alternarTema(){const t="oscuro"===raiz.getAttribute("data-theme");t?(raiz.removeAttribute("data-theme"),localStorage.setItem(CLAVE,"claro")):(raiz.setAttribute("data-theme","oscuro"),localStorage.setItem(CLAVE,"oscuro"))}const CLAVE="tema",raiz=document.documentElement;export function inicializarTema(){aplicarTemaGuardado();const t=document.getElementById("btn-dark-mode");t&&(sincronizarBoton(t),t.addEventListener("click",()=>{alternarTema(),sincronizarBoton(t)}))}